8	public class EventServiceTests
9	{
10	    private static AppDbContext CreateContext(string dbName)
11	    {
12	        var options = new DbContextOptionsBuilder<AppDbContext>()
13	            .UseInMemoryDatabase(dbName)
14	            .Options;
15	        return new AppDbContext(options);
16	    }
17	
18	    [Fact]
19	    public async Task GetEventsAsync_ReturnsEventsSortedByZeitpunktWithVenueName()
20	    {
21	        using var dbContext = CreateContext(nameof(GetEventsAsync_ReturnsEventsSortedByZeitpunktWithVenueName));
22	
23	        var venue = new Venue { Id = Guid.NewGuid(), Name = "Stadthalle Nordpark" };
24	        var room = new Room { Id = Guid.NewGuid(), Name = "Kleiner Saal", VenueId = venue.Id };
25	        dbContext.Venues.Add(venue);
26	        dbContext.Rooms.Add(room);
27	
28	        var laterEvent = new Event
29	        {
30	            Id = Guid.NewGuid(),
31	            Titel = "Später",
32	            Beschreibung = "b",
33	            DauerMinuten = 60,
34	            Altersfreigabe = 0,
35	            Zeitpunkt = new DateTime(2026, 10, 1, 20, 0, 0, DateTimeKind.Unspecified),
36	            VenueId = venue.Id,
37	            RoomId = room.Id
38	        };
39	        var earlierEvent = new Event
40	        {
41	            Id = Guid.NewGuid(),
42	            Titel = "Früher",
43	            Beschreibung = "b",
44	            DauerMinuten = 60,
45	            Altersfreigabe = 0,
46	            Zeitpunkt = new DateTime(2026, 9, 1, 19, 0, 0, DateTimeKind.Unspecified),
47	            VenueId = venue.Id,
48	            RoomId = room.Id
49	        };
50	        dbContext.Events.AddRange(laterEvent, earlierEvent);
51	        await dbContext.SaveChangesAsync();
52	
53	        var service = new EventService(dbContext);
54	        var result = await service.GetEventsAsync();
55	
56	        Assert.Equal(2, result.Count);
57	        Assert.Equal("Früher", result[0].Title);
58	        Assert.Equal("Später", result[1].Title);
59	        Assert.Equal("Stadthalle Nordpark", result[0].VenueName);
60	    }
61	
62	    private static async Task<(AppDbContext dbContext, Guid venueId, Guid roomId)> SeedVenueAndRoomAsync(string dbName)
63	    {
64	        var dbContext = CreateContext(dbName);
65	        var venue = new Venue { Id = Guid.NewGuid(), Name = "Stadthalle Nordpark" };
66	        var room = new Room { Id = Guid.NewGuid(), Name = "Kleiner Saal", VenueId = venue.Id };
67	        dbContext.Venues.Add(venue);
68	        dbContext.Rooms.Add(room);
69	        await dbContext.SaveChangesAsync();
70	        return (dbContext, venue.Id, room.Id);
71	    }
72	
73	    private static Event MakeEvent(string title, DateTime zeitpunkt, Guid venueId, Guid roomId) => new()
74	    {
75	        Id = Guid.NewGuid(),
76	        Titel = title,
77	        Beschreibung = "b",
78	        DauerMinuten = 60,
79	        Altersfreigabe = 0,
80	        Zeitpunkt = zeitpunkt,
81	        VenueId = venueId,
82	        RoomId = roomId
83	    };
84	
85	    [Fact]
86	    public async Task GetEventsAsync_WithFromAndTo_IncludesEventsExactlyOnBoundaryDates()
87	    {
88	        var (dbContext, venueId, roomId) = await SeedVenueAndRoomAsync(nameof(GetEventsAsync_WithFromAndTo_IncludesEventsExactlyOnBoundaryDates));
89	        using var _ = dbContext;
90	
91	        var onFrom = MakeEvent("Am Von-Tag früh", new DateTime(2026, 9, 5, 8, 0, 0, DateTimeKind.Unspecified), venueId, roomId);
92	        var onTo = MakeEvent("Am Bis-Tag spät", new DateTime(2026, 9, 12, 23, 0, 0, DateTimeKind.Unspecified), venueId, roomId);
93	        dbContext.Events.AddRange(onFrom, onTo);
94	        await dbContext.SaveChangesAsync();
95	
96	        var service = new EventService(dbContext);
97	        var result = await service.GetEventsAsync(new DateOnly(2026, 9, 5), new DateOnly(2026, 9, 12));
98	
99	        Assert.Equal(2, result.Count);
100	        Assert.Contains(result, e => e.Title == "Am Von-Tag früh");
101	        Assert.Contains(result, e => e.Title == "Am Bis-Tag spät");
102	    }
103	
104	    [Fact]
105	    public async Task GetEventsAsync_WithFromAndTo_ExcludesEventsOutsideRange()
106	    {
107	        var (dbContext, venueId, roomId) = await SeedVenueAndRoomAsync(nameof(GetEventsAsync_WithFromAndTo_ExcludesEventsOutsideRange));
108	        using var _ = dbContext;
109	
110	        var beforeFrom = MakeEvent("Vor Von", new DateTime(2026, 9, 4, 23, 0, 0, DateTimeKind.Unspecified), venueId, roomId);
111	        var afterTo = MakeEvent("Nach Bis", new DateTime(2026, 9, 13, 0, 0, 0, DateTimeKind.Unspecified), venueId, roomId);
112	        dbContext.Events.AddRange(beforeFrom, afterTo);
113	        await dbContext.SaveChangesAsync();
