127	        var before = MakeEvent("Davor", new DateTime(2026, 9, 4, 23, 0, 0, DateTimeKind.Unspecified), venueId, roomId);
128	        var onFrom = MakeEvent("Am Von-Tag", new DateTime(2026, 9, 5, 8, 0, 0, DateTimeKind.Unspecified), venueId, roomId);
129	        var farAfter = MakeEvent("Weit danach", new DateTime(2026, 10, 10, 22, 0, 0, DateTimeKind.Unspecified), venueId, roomId);
130	        dbContext.Events.AddRange(before, onFrom, farAfter);
